// var events1 in changestream_test.go

func waitUntilClosed(c <-chan etre.CDCEvent) error {
	for {
		select {
		case _, ok := <-c:
			if !ok {
				return nil
			}
		case <-time.After(500 * time.Millisecond):
			return fmt.Errorf("timeout waiting for streamChan to be closed")
		}
	}
}

